import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { ApplicationService } from '../../../core/services/application.service';
import { JobService } from '../../../core/services/job.service';
import { ToastService } from '../../../core/services/toast.service';
import { Application, ApplicationStatus } from '../../../core/models/application.model';
import { Job } from '../../../core/models/job.model';

@Component({
  selector: 'app-job-applications',
  templateUrl: './job-applications.component.html',
  styleUrls: ['./job-applications.component.css']
})
export class JobApplicationsComponent implements OnInit {
  jobId = '';
  job: Job | null = null;
  applications: Application[] = [];
  isLoading = true;
  hasError = false;
  updatingAppId: string | null = null;

  statusOptions: ApplicationStatus[] = ['pending', 'accepted', 'rejected', 'hired'];

  constructor(
    private route: ActivatedRoute,
    private applicationService: ApplicationService,
    private jobService: JobService,
    private toast: ToastService
  ) {}

  ngOnInit(): void {
    this.jobId = this.route.snapshot.params['jobId'] || this.route.snapshot.params['id'];
    this.fetchData();
  }

  fetchData(): void {
    this.isLoading = true;
    this.hasError = false;

    // Fetch job info
    this.jobService.getJobById(this.jobId).subscribe({
      next: (job) => {
        this.job = job;
      },
      error: () => {
        // quiet fallback
      }
    });

    // Fetch applications
    this.applicationService.getJobApplications(this.jobId).subscribe({
      next: (res) => {
        this.applications = res.data || [];
        this.isLoading = false;
      },
      error: () => {
        this.hasError = true;
        this.isLoading = false;
      }
    });
  }

 onStatusChange(app: Application, newStatus: ApplicationStatus): void {
  const appId = app._id || app.id;

  if (!appId || app.status === newStatus) return;

  this.updatingAppId = appId;

  this.applicationService.updateApplicationStatus(appId, newStatus).subscribe({
    next: (res) => {
      this.updatingAppId = null;

      // Get the actual data from backend again
      this.fetchData();

      this.toast.success(
        'Status Updated',
        `Application status updated to ${res.data.status}.`
      );
    },

    error: (err) => {
      this.updatingAppId = null;

      this.toast.error(
        'Update Failed',
        err.error?.message || 'Could not update status.'
      );
    }
  });
}

  getStatusBadgeClass(status: ApplicationStatus | string): string {
    switch (status) {
      case 'accepted':
      case 'hired':
        return 'badge-success';
      case 'rejected':
        return 'badge-danger';
      case 'pending':
      default:
        return 'badge-warning';
    }
  }

  getApplicantEmail(app: Application): string {
    if (typeof app.userId === 'object' && app.userId?.email) {
      return app.userId.email;
    }
    return 'Not provided';
  }

  getApplicantSkills(app: Application): string[] {
    if (typeof app.userId === 'object' && app.userId?.skills) {
      return app.userId.skills;
    }
    return [];
  }
}
<div class="job-applications-page container section-padding">
  <!-- Back navigation & header -->
  <div class="mb-3">
    <a routerLink="/jobs/manage" class="back-link">
      <i class="fa-solid fa-arrow-left"></i> Back to Manage Jobs
    </a>
  </div>

  <div
    class="page-header d-flex justify-content-between align-items-center mb-4 flex-wrap gap-2"
  >
    <div>
      <h1 class="page-title">Candidate Applications</h1>
      <p class="page-subtitle" *ngIf="job">
        Reviewing applicants for:
        <strong class="text-primary">{{ job.title }}</strong> ({{
          job.companyName
        }})
      </p>
    </div>
    <div class="applicants-counter badge badge-primary" *ngIf="!isLoading">
      {{ applications.length }} Total Applicants
    </div>
  </div>

  <!-- Loading State -->
  <app-loading-spinner
    *ngIf="isLoading"
    message="Fetching candidate applications..."
  ></app-loading-spinner>

  <!-- Error Alert -->
  <div class="alert alert-danger" *ngIf="hasError && !isLoading">
    <i class="fa-solid fa-circle-exclamation"></i>
    <div>
      Failed to load applications for this job.
      <button class="btn btn-sm btn-outline-danger" (click)="fetchData()">
        Retry
      </button>
    </div>
  </div>

  <!-- Empty State -->
  <app-empty-state
    *ngIf="!isLoading && !hasError && applications.length === 0"
    icon="fa-regular fa-user"
    title="No Applications Received Yet"
    message="There are no candidate submissions for this opening at the moment. As candidates apply, they will appear here ranked by skill match score."
  >
  </app-empty-state>

  <!-- Applications List -->
  <div
    class="applications-container"
    *ngIf="!isLoading && !hasError && applications.length > 0"
  >
    <div class="card applicant-card mb-3" *ngFor="let app of applications">
      <div
        class="applicant-card-header d-flex justify-content-between align-items-start gap-3 flex-wrap"
      >
        <div class="d-flex align-items-center gap-3">
          <div class="applicant-avatar">
            {{
              app.applicantName
                ? app.applicantName.charAt(0).toUpperCase()
                : "A"
            }}
          </div>
          <div>
            <h3 class="applicant-name">{{ app.applicantName }}</h3>
            <div class="applicant-email text-muted">
              <i class="fa-regular fa-envelope"></i>
              {{ getApplicantEmail(app) }}
            </div>
          </div>
        </div>

        <div class="d-flex align-items-center gap-3">
          <!-- Match Score -->
          <div
            class="match-score-pill"
            [ngClass]="{
              'match-high': (app.matchScore || 0) >= 70,
              'match-medium':
                (app.matchScore || 0) >= 40 && (app.matchScore || 0) < 70,
              'match-low': (app.matchScore || 0) < 40,
            }"
          >
            <i class="fa-solid fa-bolt"></i> {{ app.matchScore || 0 }}% Skill
            Match
          </div>

          <!-- Status Dropdown / Action  -->
           <div class="status-action-box">
            <select
              class="form-select form-select-sm status-select"
              [ngModel]="app.status"
              (ngModelChange)="onStatusChange(app, $event)"
              [disabled]="updatingAppId === (app._id || app.id)"
              name="status-{{ app._id || app.id }}"
            >
              <option *ngFor="let s of statusOptions" [value]="s">
                Status: {{ s | titlecase }}
              </option>
            </select>
          </div>
          
        </div>
      </div>

      <!-- Applicant Details Body -->
      <div class="applicant-card-body">
        <!-- Skills -->
        <div
          class="applicant-skills mb-2"
          *ngIf="getApplicantSkills(app).length > 0"
        >
          <span class="skill-label text-muted text-sm mr-2"
            >Candidate Skills:</span
          >
          <span class="tag-chip" *ngFor="let sk of getApplicantSkills(app)">
            {{ sk }}
          </span>
        </div>

        <!-- CV Link / Info -->
        <div class="cv-box">
          <span class="font-semibold text-slate-700"
            ><i class="fa-solid fa-file-pdf"></i> Resume / CV:</span
          >
          <a
            *ngIf="app.cv.startsWith('http')"
            [href]="app.cv"
            target="_blank"
            rel="noopener noreferrer"
            class="btn btn-outline btn-sm"
          >
            <i class="fa-solid fa-arrow-up-right-from-square"></i> Open Resume
            Link
          </a>
          <span *ngIf="!app.cv.startsWith('http')" class="cv-text-preview">
            {{ app.cv }}
          </span>
        </div>
      </div>
    </div>
  </div>
</div>
